INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-267b40635d436859','https://www.prothomalo.com/bangladesh/district/%E0%A6%85%E0%A6%AC%E0%A7%88%E0%A6%A7%E0%A6%AD%E0%A6%BE%E0%A6%AC%E0%A7%87-%E0%A6%A8%E0%A6%A6%E0%A7%80-%E0%A6%A5%E0%A7%87%E0%A6%95%E0%A7%87-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%8B%E0%A6%B2%E0%A6%A8-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%AC%E0%A7%8D%E0%A6%AF%E0%A6%AC%E0%A6%B8%E0%A6%BE%E0%A7%9F%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9C%E0%A6%B0%E0%A6%BF%E0%A6%AE%E0%A6%BE%E0%A6%A8%E0%A6%BE',NULL,'{"type":"News","source":"Prothom Alo","title":"অবৈধভাবে নদী থেকে বালু উত্তোলন, বালু ব্যবসায়ীকে জরিমানা","date":"2021-08-17","dateKind":"Published","district":"Rajbari","river":"Padma branch; Goalanda; Debgram","material":"Sand","topics":"Extraction; mobile court; equipment seizure; enforcement","language":"Bangla","en":"The report describes a mobile-court operation in Goalanda, Rajbari, in which a dredger was seized and a sand trader fined under the balumahal law. It also reports allegations of prolonged unauthorized extraction and political influence. The underlying court record was not collected.","bn":"রাজবাড়ীর গোয়ালন্দে ভ্রাম্যমাণ আদালতের অভিযানে খননযন্ত্র জব্দ ও বালুমহাল আইনে এক বালু ব্যবসায়ীকে জরিমানার কথা প্রতিবেদনে রয়েছে। দীর্ঘদিন অনুমতি ছাড়া উত্তোলন ও রাজনৈতিক প্রভাবের অভিযোগও উঠে আসে। মূল আদালতের নথি সংগ্রহ করা হয়নি।","evidence":"Bangla article text; visible publication date","flag":"Verify enforcement record","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/%E0%A6%85%E0%A6%AC%E0%A7%88%E0%A6%A7%E0%A6%AD%E0%A6%BE%E0%A6%AC%E0%A7%87-%E0%A6%A8%E0%A6%A6%E0%A7%80-%E0%A6%A5%E0%A7%87%E0%A6%95%E0%A7%87-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%8B%E0%A6%B2%E0%A6%A8-%E0%A6%AC%E0%A6%BE%E0%A6%B2%E0%A7%81-%E0%A6%AC%E0%A7%8D%E0%A6%AF%E0%A6%AC%E0%A6%B8%E0%A6%BE%E0%A7%9F%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9C%E0%A