INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-ff14060983cca68d','https://www.prothomalo.com/bangladesh/district/bgo3wcpzxi',NULL,'{"type":"News","source":"Prothom Alo","title":"শিবালয়ে বালু উত্তোলন নিয়ে দ্বন্দ্বে আবারও গুলিবর্ষণ","date":"2026-05-10","dateKind":"Published","district":"Manikganj","river":"Jamuna; Shibalay; Alokdia","material":"Sand","topics":"Extraction; conflict; leasing","language":"Bangla","en":"The report describes gunfire during a dispute over extraction in a leased Jamuna area. It also recounts an earlier killing and an ongoing police investigation.","bn":"যমুনার ইজারাকৃত এলাকায় উত্তোলন নিয়ে দ্বন্দ্বে গুলিবর্ষণের খবর রয়েছে। আগের হত্যাকাণ্ড এবং পুলিশের চলমান তদন্তের কথাও প্রতিবেদনে বলা হয়েছে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/bgo3wcpzxi","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified.","id":"BSW-ff14060983cca68d","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:05.488Z"}','2026-10-11T23:19:05.488Z');
