INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-c9eac48c561e4a6f','https://www.dhakatribune.com/bangladesh/court/417605/high-court-orders-halt-to-illegal-sand-extraction',NULL,'{"type":"News","source":"Dhaka Tribune","title":"HC orders halt to illegal sand extraction from Tentulia River","date":"2026-08-16","dateKind":"Published","district":"Patuakhali","river":"Tentulia; Bauphal","material":"Sand","topics":"Court orders; hydrographic survey; river naming","language":"English","en":"The High Court reportedly ordered suspension of unauthorized extraction in erosion-prone Tentulia areas. The report also describes directions on hydrographic surveys and correcting the river name in government records.","bn":"তেঁতুলিয়ার ভাঙনপ্রবণ এলাকায় অনুমতিবিহীন উত্তোলন স্থগিতের আদালতের নির্দেশের খবর রয়েছে। হাইড্রোগ্রাফিক জরিপ ও সরকারি নথিতে নদীর নাম সংশোধনের কথাও বলা হয়েছে।","evidence":"Article text and source date label","flag":"Review source-attributed claims","documentId":"","otherDate":"","url":"https://www.dhakatribune.com/bangladesh/court/417605/high-court-orders-halt-to-illegal-sand-extraction","alternateUrl":"","notes":"Backfill from January 1, 2026. Source-attributed paraphrases; claims not independently verified. Underlying court instrument has not been independently collected.","id":"BSW-c9eac48c561e4a6f","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-11T23:19:17.574Z"}','2026-10-11T23:19:17.574Z');
