INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-7d077cf5596c7a65','https://www.thedailystar.net/news/bangladesh/news/stone-extraction-halted-dinajpurs-maddhapara-mining-company-due-explosive-shortage-4179541',NULL,'{"type":"Context","source":"The Daily Star","title":"Stone extraction halted at Dinajpur''s Maddhapara mining company due to explosive shortage","date":"2026-05-19","dateKind":"Publication","district":"Dinajpur","river":"Maddhapara underground granite mine","material":"Stone","topics":"Supply; Industrial mining","language":"English","en":"The Daily Star reports that Maddhapara Granite Mining Company suspended extraction after imported explosive stocks ran out. This provides construction-stone supply context; it concerns an underground hard-rock mine rather than river sediment extraction.","bn":"ডেইলি স্টার জানায়, আমদানি করা বিস্ফোরকের মজুত ফুরিয়ে যাওয়ায় মধ্যপাড়া গ্রানাইট খনিতে পাথর উত্তোলন বন্ধ হয়। নির্মাণপাথরের সরবরাহের প্রেক্ষাপট হিসেবে এটি রাখা হয়েছে; ঘটনাটি নদীর বালু-পাথর উত্তোলনের নয়, ভূগর্ভস্থ কঠিন শিলার খনির।","evidence":"Retrieved article text and labeled source date","flag":"Scope context: underground granite mining. Expected restart dates are forecasts, not verified outcomes.","documentId":"","otherDate":"Updated 2026-05-19 19:56","url":"https://www.thedailystar.net/news/bangladesh/news/stone-extraction-halted-dinajpurs-maddhapara-mining-company-due-explosive-shortage-4179541","alternateUrl":"","notes":"Collected 2026-10-12. Scope context: underground granite mining. Expected restart dates are forecasts, not verified outcomes.","id":"BSW-7d077cf5596c7a65","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:47.780Z"}','2026-10-12T13:18:47.780Z');
