INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-18c2302e9016beac','https://www.daily-sun.com/20/891496',NULL,'{"type":"Context","source":"Daily Sun","title":"River sand could be Bangladesh’s ‘white gold’","date":"2026-08-10","dateKind":"Publication","district":"Multiple districts","river":"Brahmaputra-Jamuna; Padma; Teesta","material":"Sand; Silica","topics":"Resource potential; Processing; Research reporting","language":"English","en":"Daily Sun discusses a researcher’s proposed use of Bangladesh river sand as an industrial silica resource while acknowledging that semiconductor-grade suitability remains unproven. The report calls for further testing and phased processing research.","bn":"ডেইলি সান বাংলাদেশের নদীর বালু থেকে শিল্পে ব্যবহারযোগ্য সিলিকা উৎপাদনের সম্ভাবনা নিয়ে এক গবেষকের প্রস্তাব তুলে ধরে। সেমিকন্ডাক্টর শিল্পে উপযোগিতা এখনো প্রমাণিত নয় বলে প্রতিবেদনে স্বীকার করা হয়েছে; আরও পরীক্ষা ও পর্যায়ক্রমিক গবেষণার কথা বলা হয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Research reported by newspaper; underlying review not retrieved. The source equates 99.99% with 9N, an internal purity-notation inconsistency. Daily Sun credits Kaler Kantho; DredgeWire republishes this report on 2026-08-12.","documentId":"","otherDate":"Updated 2026-08-10 16:44; DredgeWire repost 2026-08-12","url":"https://www.daily-sun.com/20/891496","alternateUrl":"https://dredgewire.com/river-sand-could-be-bangladeshs-white-gold/","notes":"Collected 2026-10-12. Research reported by newspaper; underlying review not retrieved. The source equates 99.99% with 9N, an internal purity-notation inconsistency. Daily Sun credits Kaler Kantho; DredgeWire republishes this report on 2026-08-12.","id":"BSW-18c2302e9016beac","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:47.893Z"}','2026-10-12T13:18:47.893Z');
