INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-6879d45ea211de1a','https://www.newagebd.net/post/country/316602/collapsed-road-in-jhenaidah-left-unrepaired-for-2-years',NULL,'{"type":"News","source":"New Age","title":"Collapsed road in Jhenaidah left unrepaired for 2 years","date":"2026-10-05","dateKind":"Publication","district":"Jhenaidah","river":"D-7N canal, Harinakundu","material":"Sand","topics":"Infrastructure damage; Canal excavation; Complaints","language":"English","en":"New Age reports prolonged road damage beside a Harinakundu canal. Residents link the collapse to canal excavation and unauthorized sand extraction; a Water Development Board engineer acknowledges extraction irregularities and says bank repairs are under discussion.","bn":"নিউ এজ হরিণাকুণ্ডুতে খালের পাশের সড়ক দীর্ঘদিন ক্ষতিগ্রস্ত থাকার খবর জানায়। স্থানীয়রা খাল খনন ও অননুমোদিত বালু উত্তোলনকে ধসের কারণ হিসেবে উল্লেখ করেন; পাউবোর এক প্রকৌশলী উত্তোলনে অনিয়মের কথা স্বীকার করে পাড় মেরামত নিয়ে আলোচনার কথা জানান।","evidence":"Retrieved article text and labeled source date","flag":"Causation is attributed to residents and officials; no independent engineering assessment was retrieved.","documentId":"","otherDate":"","url":"https://www.newagebd.net/post/country/316602/collapsed-road-in-jhenaidah-left-unrepaired-for-2-years","alternateUrl":"","notes":"Collected 2026-10-12. Causation is attributed to residents and officials; no independent engineering assessment was retrieved.","id":"BSW-6879d45ea211de1a","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.004Z"}','2026-10-12T13:18:48.004Z');
