INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-301e714b3945a938','https://bonikbarta.com/bangladesh/C5SkAATgjsObKHyy',NULL,'{"type":"News","source":"Bonik Barta","title":"পলি জমে অনিরাপদ হয়ে পড়ছে চট্টগ্রামের সন্দ্বীপ চ্যানেল","date":"2026-01-02","dateKind":"Publication","district":"Chattogram","river":"Sandwip Channel; Kumira-Guptachhara route","material":"Sand","topics":"Navigation; Dredging; Enforcement","language":"Bangla","en":"Bonik Barta reports navigation and passenger-safety concerns in Sandwip Channel involving sand extraction, dredgers, bulkheads and sediment accumulation. It says BIWTA requested joint enforcement and restrictions on extraction along affected routes.","bn":"বণিক বার্তা সন্দ্বীপ চ্যানেলে বালু উত্তোলন, ড্রেজার-বাল্কহেড চলাচল ও পলি জমার সঙ্গে সংশ্লিষ্ট নৌচলাচল ও যাত্রীনিরাপত্তার উদ্বেগ জানায়। প্রতিবেদনে বলা হয়, বিআইডব্লিউটিএ সংশ্লিষ্ট নৌপথে উত্তোলন নিয়ন্ত্রণ ও যৌথ অভিযানের অনুরোধ করেছে।","evidence":"Retrieved article text and labeled source date","flag":"Agency letters and statutory interpretations are reported by the newspaper; original letters and provisions were not independently reviewed.","documentId":"","otherDate":"","url":"https://bonikbarta.com/bangladesh/C5SkAATgjsObKHyy","alternateUrl":"","notes":"Collected 2026-10-12. Agency letters and statutory interpretations are reported by the newspaper; original letters and provisions were not independently reviewed.","id":"BSW-301e714b3945a938","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.127Z"}','2026-10-12T13:18:48.127Z');
