INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-594f95b4b01c4ed8','https://bangla.bdnews24.com/samagrabangladesh/13912488f241',NULL,'{"type":"News","source":"bdnews24.com Bangla","title":"বালু তুলতে গিয়ে দুই নৌকার মাঝে চাপা, শ্রমিকের মৃত্যু","date":"2026-08-05","dateKind":"Publication","district":"Netrokona","river":"Mahadeo River, Kalmakanda","material":"Sand","topics":"Worker safety; Fatality; Enforcement","language":"Bangla","en":"bdnews24 reports that a worker died after being crushed between boats while loading sand from the Mahadeo River. Police described the extraction as unauthorized and noted that a shortage of patrol boats constrains enforcement.","bn":"বিডিনিউজ২৪ জানায়, মহাদেও নদ থেকে বালু বোঝাইয়ের সময় দুই নৌকার মাঝে চাপা পড়ে এক শ্রমিক মারা যান। পুলিশ উত্তোলনকে অবৈধ বলে উল্লেখ করে এবং পর্যাপ্ত নৌযানের অভাবে অভিযান পরিচালনায় সীমাবদ্ধতার কথা জানায়।","evidence":"Retrieved article text and labeled source date","flag":"Publication date is 2026-08-05; September update is separately retained. Legality is attributed to police.","documentId":"","otherDate":"Updated 2026-09-11","url":"https://bangla.bdnews24.com/samagrabangladesh/13912488f241","alternateUrl":"","notes":"Collected 2026-10-12. Publication date is 2026-08-05; September update is separately retained. Legality is attributed to police.","id":"BSW-594f95b4b01c4ed8","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.224Z"}','2026-10-12T13:18:48.224Z');
