INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-4eaec221f5243578','https://www.prothomalo.com/opinion/editorial/z6cmjw421b',NULL,'{"type":"Editorial","source":"Prothom Alo","title":"বালুমহাল ইজারা দেওয়ার সুযোগ নেই","date":"2026-03-19","dateKind":"Publication","district":"Rajshahi","river":"Padma River, Bagha","material":"Sand","topics":"Leasing; Agriculture; River protection","language":"Bangla","en":"Prothom Alo’s editorial opposes renewed sand leasing near recovered agricultural land in Bagha. It argues that lease decisions should consider farmers’ livelihoods and river-protection works rather than revenue alone.","bn":"প্রথম আলোর সম্পাদকীয় বাঘায় জেগে ওঠা কৃষিজমির কাছে পুনরায় বালুমহাল ইজারা দেওয়ার বিরোধিতা করে। শুধু রাজস্ব নয়, কৃষকের জীবিকা ও নদীরক্ষা কাজের সুরক্ষা বিবেচনায় সিদ্ধান্ত নেওয়ার আহ্বান জানানো হয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Editorial position and predicted impacts, not an independently verified legal prohibition.","documentId":"","otherDate":"","url":"https://www.prothomalo.com/opinion/editorial/z6cmjw421b","alternateUrl":"","notes":"Collected 2026-10-12. Editorial position and predicted impacts, not an independently verified legal prohibition.","id":"BSW-4eaec221f5243578","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.342Z"}','2026-10-12T13:18:48.342Z');
