INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-ea6e262c67f3176d','https://www.jugantor.com/country-news/1114535',NULL,'{"type":"News","source":"Jugantor","title":"বালু উত্তোলনে শত শত কোটি টাকা লোপাটের অভিযোগ, হাইকোর্টে রিট","date":"2026-06-16","dateKind":"Publication","district":"Cox’s Bazar","river":"Maheshkhali coast; Matarbari port access road","material":"Sand","topics":"Public procurement; Royalty; Litigation; Environmental assessment","language":"Bangla","en":"Jugantor reports a public-interest petition challenging sand-extraction approval and pricing for the Matarbari port access road. The petitioner alleges noncompetitive allocation, revenue losses and missing environmental assessment; these are allegations rather than established court findings.","bn":"যুগান্তর মাতারবাড়ী বন্দর সংযোগ সড়কের জন্য বালু উত্তোলনের অনুমোদন ও মূল্য নির্ধারণ চ্যালেঞ্জ করে রিট দায়েরের খবর জানায়। আবেদনকারী প্রতিযোগিতাহীন বরাদ্দ, রাজস্ব ক্ষতি ও পরিবেশগত মূল্যায়নের ঘাটতির অভিযোগ করেন; এগুলো আদালতে প্রমাণিত সিদ্ধান্ত হিসেবে ধরা হয়নি।","evidence":"Retrieved article text and labeled source date","flag":"Press report of a petition, not a court order. Other retrieved reporting differs on whether filing occurred June 15 or 16; publication date is June 16. Quantities and alleged losses not independently verified.","documentId":"","otherDate":"","url":"https://www.jugantor.com/country-news/1114535","alternateUrl":"","notes":"Collected 2026-10-12. Press report of a petition, not a court order. Other retrieved reporting differs on whether filing occurred June 15 or 16; publication date is June 16. Quantities and alleged losses not independently verified.","id":"BSW-ea6e262c67f3176d","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.448Z"}','2026-10-12T13:18:48.448Z');
