INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-86b86fc874553157','https://bangla.bdnews24.com/samagrabangladesh/hux0283jsj',NULL,'{"type":"News","source":"bdnews24.com Bangla","title":"শরীয়তপুরে পদ্মার তীররক্ষা বাঁধের ৪০ মিটার নদীতে বিলীন, আতঙ্ক","date":"2026-10-02","dateKind":"Publication","district":"Shariatpur","river":"Padma River, Sureshwar, Naria","material":"Sand","topics":"Bank protection; Erosion; Infrastructure","language":"Bangla","en":"bdnews24 reports collapse and cracking at the Padma bank-protection works in Sureshwar. Residents attribute worsening erosion to sand extraction, while the Water Development Board reports emergency geobag placement.","bn":"বিডিনিউজ২৪ সুরেশ্বরে পদ্মার তীররক্ষা কাজে ধস ও ফাটলের খবর জানায়। স্থানীয়রা বালু উত্তোলনকে ভাঙন বৃদ্ধির কারণ হিসেবে উল্লেখ করেন; পানি উন্নয়ন বোর্ড জরুরি জিওব্যাগ ফেলার কথা জানায়।","evidence":"Retrieved article text and labeled source date","flag":"Causal attribution is from residents. Headline states 40 m collapsed, while an engineer’s quoted account gives 30 m; no single collapse length is asserted in the summary.","documentId":"","otherDate":"","url":"https://bangla.bdnews24.com/samagrabangladesh/hux0283jsj","alternateUrl":"","notes":"Collected 2026-10-12. Causal attribution is from residents. Headline states 40 m collapsed, while an engineer’s quoted account gives 30 m; no single collapse length is asserted in the summary.","id":"BSW-86b86fc874553157","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.557Z"}','2026-10-12T13:18:48.557Z');
