INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-ff3560f755bb5d33','https://www.jugantor.com/tp-lastpage/1163209',NULL,'{"type":"News","source":"Jugantor","title":"বরিশালে অবাধে নদীর বালু উত্তোলন, ভাঙনের শঙ্কা","date":"2026-10-03","dateKind":"Publication","district":"Barishal","river":"Jhunahar; Tentulia; Karkhana","material":"Sand","topics":"Unauthorized extraction; Governance; Erosion risk","language":"Bangla","en":"Jugantor reports nighttime sand extraction and residents’ concerns about bank erosion in Barishal. It records allegations of political protection alongside denials; the district administrator says no river sand leases were issued that year and that raids continue.","bn":"যুগান্তর বরিশালে রাতে বালু উত্তোলন ও নদীপাড়ের মানুষের ভাঙনের আশঙ্কার কথা জানায়। রাজনৈতিক প্রশ্রয়ের অভিযোগের পাশাপাশি সংশ্লিষ্টদের অস্বীকৃতিও তুলে ধরা হয়েছে; জেলা প্রশাসক জানান, ওই বছর নদীতে বালুমহাল ইজারা দেওয়া হয়নি এবং অভিযান চলছে।","evidence":"Retrieved article text and labeled source date","flag":"Includes disputed allegations and official denials. No independent verification of operators or permits.","documentId":"","otherDate":"","url":"https://www.jugantor.com/tp-lastpage/1163209","alternateUrl":"","notes":"Collected 2026-10-12. Includes disputed allegations and official denials. No independent verification of operators or permits.","id":"BSW-ff3560f755bb5d33","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.667Z"}','2026-10-12T13:18:48.667Z');
