INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-33a724a321763830','https://theclimatewatch.com/journalists-attacked-covering-sand-mining-in-coxs-bazar/',NULL,'{"type":"News","source":"The Climate Watch","title":"Journalists attacked covering sand mining in Cox’s Bazar","date":"2026-03-03","dateKind":"Publication","district":"Cox’s Bazar","river":"Ichhachhari stream, Harbang, Chakaria","material":"Sand","topics":"Press freedom; Worker/site safety; Lease enforcement","language":"English","en":"The Climate Watch reports an attack on journalists documenting sand extraction in Ichhachhari stream. It describes mechanized extraction, alleged lease violations and intimidation, and records officials’ promises to investigate.","bn":"দ্য ক্লাইমেট ওয়াচ ইছাছড়ি ছড়ায় বালু উত্তোলনের ছবি ধারণ করতে গিয়ে সাংবাদিকদের ওপর হামলার খবর জানায়। যান্ত্রিক উত্তোলন, ইজারার শর্ত ভঙ্গ ও ভয়ভীতির অভিযোগ তুলে ধরে কর্মকর্তাদের তদন্তের আশ্বাসও উল্লেখ করা হয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Reported attack occurred February 22; publication is March 3. Allegations, dimensions and legal interpretation are not independently verified.","documentId":"","otherDate":"Reported incident 2026-02-22","url":"https://theclimatewatch.com/journalists-attacked-covering-sand-mining-in-coxs-bazar/","alternateUrl":"","notes":"Collected 2026-10-12. Reported attack occurred February 22; publication is March 3. Allegations, dimensions and legal interpretation are not independently verified.","id":"BSW-33a724a321763830","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:48.877Z"}','2026-10-12T13:18:48.877Z');
