INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-efe2daab9180e7da','https://www.prothomalo.com/bangladesh/district/d6lnzvc35x',NULL,'{"type":"News","source":"Prothom Alo","title":"সুনামগঞ্জে ৯ দিনে ৫ কোটি টাকার বালু লুটের অভিযোগে ৩৭ জনের নামে মামলা","date":"2026-10-08","dateKind":"Publication","district":"Sunamganj","river":"Morachela River, Sonapur, Dowarabazar","material":"Sand","topics":"Enforcement; Environmental damage; Criminal complaint","language":"Bangla","en":"Prothom Alo reports that the Department of Environment filed a case alleging unlicensed sand extraction and bank cutting in the Morachela River. The district administration said task-force operations would continue.","bn":"প্রথম আলো জানায়, মরাচেলা নদীতে ইজারাবিহীন বালু উত্তোলন ও পাড় কাটার অভিযোগে পরিবেশ অধিদপ্তর মামলা করেছে। জেলা প্রশাসন টাস্কফোর্সের অভিযান অব্যাহত রাখার কথা জানিয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Case allegations and estimated extraction/value are attributed to the report; the FIR and later outcome were not retrieved.","documentId":"","otherDate":"","url":"https://www.prothomalo.com/bangladesh/district/d6lnzvc35x","alternateUrl":"","notes":"Collected 2026-10-12. Case allegations and estimated extraction/value are attributed to the report; the FIR and later outcome were not retrieved.","id":"BSW-efe2daab9180e7da","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:49.000Z"}','2026-10-12T13:18:49.000Z');
