INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-688ef0859b4a2314','https://www.jagonews24.com/country/news/1165519',NULL,'{"type":"News","source":"Jago News24","title":"অবৈধভাবে বালু তোলায় বরিশালে ড্রেজার-বাল্কহেড জব্দ, জরিমানা সাড়ে ৫ লাখ","date":"2026-10-07","dateKind":"Publication","district":"Barishal","river":"Arial Khan River near Shaistabad","material":"Sand","topics":"Enforcement; Mobile court; Equipment seizure","language":"Bangla","en":"Jago News24 reports a joint Coast Guard and local-administration operation against sand extraction near Shaistabad. It says two dredgers and three bulkheads were seized, owners were fined and the vessels were later released after undertakings.","bn":"জাগো নিউজ২৪ শায়েস্তাবাদের কাছে বালু উত্তোলনের বিরুদ্ধে কোস্ট গার্ড ও স্থানীয় প্রশাসনের যৌথ অভিযানের খবর জানায়। প্রতিবেদনে দুটি ড্রেজার ও তিনটি বাল্কহেড জব্দ, মালিকদের জরিমানা এবং মুচলেকা নিয়ে পরে নৌযান ছেড়ে দেওয়ার কথা বলা হয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Based on a reported Coast Guard briefing; original release and mobile-court order were not retrieved. Body dates the operation October 6, publication October 7.","documentId":"","otherDate":"Operation reported 2026-10-06","url":"https://www.jagonews24.com/country/news/1165519","alternateUrl":"","notes":"Collected 2026-10-12. Based on a reported Coast Guard briefing; original release and mobile-court order were not retrieved. Body dates the operation October 6, publication October 7.","id":"BSW-688ef0859b4a2314","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:49.136Z"}','2026-10-12T13:18:49.136Z');
