INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-e4c3151f0d46251c','https://sunamkantha.com/11784',NULL,'{"type":"Editorial","source":"Daily Sunamkantha","title":"ধোপাজানে বালু লুট বন্ধে কার্যকর পদক্ষেপ নিন","date":"2026-10-04","dateKind":"Labeled upload/publication date","district":"Sunamganj","river":"Dhopajan-Chalti River","material":"Sand; Stone","topics":"Editorial; Surveillance; Complaints; Enforcement","language":"Bangla","en":"Daily Sunamkantha’s editorial calls for effective action against alleged extraction in Dhopajan-Chalti despite CCTV monitoring. It contrasts residents’ allegations with police claims that extraction has stopped and urges investigation of the discrepancy.","bn":"দৈনিক সুনামকণ্ঠের সম্পাদকীয় সিসি ক্যামেরার নজরদারি থাকা সত্ত্বেও ধোপাজান-চলতিতে বালু উত্তোলনের অভিযোগ তদন্ত ও কার্যকর ব্যবস্থা নেওয়ার আহ্বান জানায়। স্থানীয়দের অভিযোগ এবং উত্তোলন বন্ধ হয়েছে বলে পুলিশের বক্তব্যের বিরোধটি খতিয়ে দেখতে বলা হয়েছে।","evidence":"Retrieved article text and labeled source date","flag":"Editorial based on disputed allegations; police deny continuing extraction. Upload and update dates both October 4.","documentId":"","otherDate":"","url":"https://sunamkantha.com/11784","alternateUrl":"","notes":"Collected 2026-10-12. Editorial based on disputed allegations; police deny continuing extraction. Upload and update dates both October 4.","id":"BSW-e4c3151f0d46251c","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-12T13:18:49.364Z"}','2026-10-12T13:18:49.364Z');
