INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-fa956b35b27f2c97','https://www.thedailystar.net/star-weekend/spotlight/news/the-jinjirum-dies-slow-death-1744762',NULL,'{"type":"News","source":"The Daily Star","title":"A River Dies in Kurigram","date":"2019-05-16","dateKind":"Published","district":"Kurigram; Jamalpur","river":"Jinjirum","material":"Sand","topics":"Extraction; historical reporting","language":"English","en":"The Daily Star describes declining river flow and bank erosion around Rowmari, linking pressures to road barriers and sand extraction. Residents describe damage to livelihoods along the river.","bn":"রৌমারীতে নদীর প্রবাহ কমে যাওয়া ও ভাঙনের সঙ্গে সড়কের প্রতিবন্ধকতা এবং বালু উত্তোলনের সম্পর্ক তুলে ধরেছে ডেইলি স্টার। নদীনির্ভর জীবিকার ক্ষতির কথাও জানিয়েছেন বাসিন্দারা।","evidence":"Article text and publisher date label/metadata","flag":"Reported claims; independent verification needed","documentId":"","otherDate":"","url":"https://www.thedailystar.net/star-weekend/spotlight/news/the-jinjirum-dies-slow-death-1744762","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved.","id":"BSW-fa956b35b27f2c97","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:20.536Z"}','2026-10-13T01:53:20.536Z');
