INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-3d2d9d9f5748349f','https://iopscience.iop.org/article/10.1088/1748-9326/ad6016','10.1088/1748-9326/ad6016','{"type":"Research","source":"IOP / Environmental Research Letters","title":"Sand mining across the Ganges–Brahmaputra–Meghna Catchment; assessment of activity and implications for sediment delivery","date":"2024-07-19","dateKind":"First published online","district":"Bangladesh; transboundary catchment","river":"Ganges; Brahmaputra; Meghna","material":"Sand","topics":"Extraction; research; governance","language":"English","en":"Daham and colleagues use remote sensing to assess extraction across the GBM catchment during 2016–2021. Their abstract reports widespread activity and implications for delta sediment delivery; catchment estimates are not Bangladesh-only totals.","bn":"দাহাম ও সহলেখকেরা দূর অনুধাবনের মাধ্যমে ২০১৬–২০২১ সালে গঙ্গা–ব্রহ্মপুত্র–মেঘনা অববাহিকায় বালু উত্তোলন মূল্যায়ন করেছেন। সারসংক্ষেপে বিস্তৃত কার্যক্রম ও বদ্বীপে পলি সরবরাহের গুরুত্ব তুলে ধরা হয়েছে; অববাহিকার হিসাব শুধু বাংলাদেশের নয়।","evidence":"Publisher abstract and article metadata","flag":"Abstract reviewed; full methods not assessed","documentId":"10.1088/1748-9326/ad6016","otherDate":"Issue August 2024","url":"https://iopscience.iop.org/article/10.1088/1748-9326/ad6016","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved. Authors: Afrah Daham, Gregory H. Sambrook Smith, Andrew P. Nicholas, Andrea Gasparotto, Julian Clark, Tahmina Yasmin. Study period 2016–2021; journal issue August 2024. Transboundary catchment scope.","id":"BSW-3d2d9d9f5748349f","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:32.497Z"}','2026-10-13T01:53:32.497Z');
