INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-5ed3fde032837a27','https://onlinelibrary.wiley.com/doi/abs/10.1111/dech.12870','10.1111/dech.12870','{"type":"Research","source":"Wiley / Development and Change","title":"Governing Artisanal and Small-scale Sand Mining in Bangladesh","date":"2025-03-21","dateKind":"First published online","district":"Bangladesh","river":"Multiple river sites","material":"Sand","topics":"Extraction; research; governance","language":"English","en":"Suykens and colleagues'' abstract compares governance of mechanized and artisanal sand extraction in Bangladesh using interviews and group discussions. It argues that leasing, unequal power and profit incentives require context-sensitive reforms.","bn":"সুইকেন্স ও সহলেখকদের সারসংক্ষেপে সাক্ষাৎকার ও দলীয় আলোচনার মাধ্যমে বাংলাদেশের যান্ত্রিক ও ক্ষুদ্র বালু উত্তোলনের শাসনব্যবস্থা তুলনা করা হয়েছে। ইজারা, ক্ষমতার অসমতা এবং লাভের প্রণোদনা বিবেচনায় সংস্কারের কথা বলা হয়েছে।","evidence":"Publisher abstract and article metadata","flag":"Abstract reviewed; full methods not assessed","documentId":"10.1111/dech.12870","otherDate":"Issue-year metadata 2025-01-01","url":"https://onlinelibrary.wiley.com/doi/abs/10.1111/dech.12870","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved. Authors: Bert Suykens, Atique Rahman, Shameem Reza Khan, Sabbir Ahmed Dhali. First-published label March 21, 2025 takes precedence over issue-year metadata January 1, 2025.","id":"BSW-5ed3fde032837a27","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:32.604Z"}','2026-10-13T01:53:32.604Z');
