INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-77bdef86a6c38aaf','https://www.dhakatribune.com/bangladesh/election/157837/sylhet-4-constituency-stone-quarry-syndicate',NULL,'{"type":"Context","source":"Dhaka Tribune","title":"Sylhet 4 constituency: Stone quarry syndicate could prove AL’s undoing","date":"2018-10-10","dateKind":"Published","district":"Sylhet","river":"Bholaganj; Jaflong; Bichanakandi; stone quarries","material":"Stone","topics":"Extraction; historical reporting","language":"English","en":"Dhaka Tribune''s election feature describes allegations about quarry syndicates and local political influence in Sylhet-4. It places extraction governance within electoral competition rather than reporting a new enforcement decision.","bn":"সিলেট-৪ আসনের নির্বাচনী প্রতিবেদনে পাথর কোয়ারির চক্র ও রাজনৈতিক প্রভাবের অভিযোগ তুলে ধরেছে ঢাকা ট্রিবিউন। উত্তোলনের ব্যবস্থাপনাকে নির্বাচনী প্রতিযোগিতার প্রেক্ষাপটে আলোচনা করা হয়েছে।","evidence":"Article text and publisher date label/metadata","flag":"Reported claims; independent verification needed","documentId":"","otherDate":"","url":"https://www.dhakatribune.com/bangladesh/election/157837/sylhet-4-constituency-stone-quarry-syndicate","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved.","id":"BSW-77bdef86a6c38aaf","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:46.214Z"}','2026-10-13T01:53:46.214Z');
