INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-b0400a24d1325bc6','https://www.dhakatribune.com/bangladesh/11786/workers-dogged-by-dust-and-disease',NULL,'{"type":"News","source":"Dhaka Tribune","title":"Workers dogged by dust and disease","date":"2016-12-11","dateKind":"Published","district":"Sylhet","river":"Jaflong; Bholaganj","material":"Stone","topics":"Extraction; historical reporting","language":"English","en":"Dhaka Tribune reports quarry and crushing workers'' health concerns, including dust exposure and difficulty accessing care. Clinicians and a researcher describe occupational risks; this is reporting, not a clinical assessment of individuals.","bn":"পাথর উত্তোলন ও ভাঙার শ্রমিকদের ধুলার সংস্পর্শ এবং চিকিৎসা পাওয়ার সমস্যা তুলে ধরেছে ঢাকা ট্রিবিউন। চিকিৎসক ও গবেষকের বক্তব্যে পেশাগত ঝুঁকি রয়েছে; এটি ব্যক্তির চিকিৎসাগত মূল্যায়ন নয়।","evidence":"Article text and publisher date label/metadata","flag":"Reported claims; independent verification needed","documentId":"","otherDate":"","url":"https://www.dhakatribune.com/bangladesh/11786/workers-dogged-by-dust-and-disease","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved.","id":"BSW-b0400a24d1325bc6","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:46.455Z"}','2026-10-13T01:53:46.455Z');
