INSERT OR IGNORE INTO archive_records (id,canonical_url,doi,data,created_at) VALUES ('BSW-88af86d76493deab','https://www.dhakatribune.com/bangladesh/11723/childhood-crushed-under-weight-of-stones',NULL,'{"type":"News","source":"Dhaka Tribune","title":"Childhood crushed under weight of stones","date":"2016-12-10","dateKind":"Published","district":"Sylhet","river":"Piyain; Jaflong","material":"Stone","topics":"Extraction; historical reporting","language":"English","en":"Dhaka Tribune describes children collecting stone with their families and the pressure of poverty on schooling. Workers and quarry representatives discuss manual extraction and restrictions; quoted employment totals were not independently verified.","bn":"পরিবারের সঙ্গে শিশুদের পাথর সংগ্রহ এবং দারিদ্র্যের কারণে পড়াশোনায় চাপের খবর দিয়েছে ঢাকা ট্রিবিউন। হাত দিয়ে উত্তোলন ও বিধিনিষেধের আলোচনা রয়েছে; শ্রমিকের সংখ্যার দাবি স্বতন্ত্রভাবে যাচাই হয়নি।","evidence":"Article text and publisher date label/metadata","flag":"Reported claims; independent verification needed","documentId":"","otherDate":"","url":"https://www.dhakatribune.com/bangladesh/11723/childhood-crushed-under-weight-of-stones","alternateUrl":"","notes":"Source-backed attributed summary. Publication/update labels are kept separate from retrieval dates. Court orders, permits and case files mentioned by the press were not independently retrieved.","id":"BSW-88af86d76493deab","decision":"Pending","reviewNotes":"","collectedAt":"2026-10-13T01:53:46.579Z"}','2026-10-13T01:53:46.579Z');
